# Analyze the differences
inputs = ['bvj', 'wdhf', 'vu', 'ddacx', 'vwxdb']
outputs = ['bvj', 'wdhf', 'vu', 'ddabc', 'vwxivb']

# Focus on the changed pairs
changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))
        print(f"Changed pair {i}: '{inp}' -> '{outp}'")

print("\nAnalyzing differences:")
for idx, inp, outp in changed_pairs:
    print(f"'{inp}' vs '{outp}':")
    # Find where they differ
    for j, (c1, c2) in enumerate(zip(inp, outp)):
        if c1 != c2:
            print(f"  Position {j}: '{c1}' -> '{c2}'")
    if len(outp) != len(inp):
        print(f"  Length changed: {len(inp)} -> {len(outp)}")

